import os
import subprocess

from .resolve import resolve


def run(argv, timeout=None):
    """解析 ``argv[0]`` 并执行，返回 ``subprocess.CompletedProcess``。"""
    if not argv:
        raise ValueError("argv must not be empty")

    path = resolve(argv[0])

    # 检查是否是批处理脚本（.cmd 或 .bat）
    # 这些文件不能直接由 CreateProcess 执行，必须通过 cmd.exe 启动
    path_lower = path.lower()
    if path_lower.endswith('.cmd') or path_lower.endswith('.bat'):
        # 使用 cmd.exe /c 来执行批处理脚本
        # /c 参数表示执行完命令后退出
        cmd_args = ['cmd.exe', '/c', path] + [str(a) for a in argv[1:]]
        return subprocess.run(
            cmd_args,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    else:
        # 直接执行可执行文件
        return subprocess.run(
            [path] + [str(a) for a in argv[1:]],
            capture_output=True,
            text=True,
            timeout=timeout,
        )


def run_ok(argv, timeout=None):
    """执行并断言成功；返回标准输出（已去掉尾部空白）。"""
    proc = run(argv, timeout=timeout)
    if proc.returncode != 0:
        raise RuntimeError(
            "command %r exited with %d: %s" % (argv[0], proc.returncode, proc.stderr.strip())
        )
    return proc.stdout.strip()
